import React, { useState } from "react";
import Navbar from "./components/Navbar";
import Chatbot from "./components/Chatbot";

import Home from "./components/Home";
import About from "./components/About";
import Events from "./components/Events";
import Login from "./components/Login";
import Register from "./components/Register";

export default function App() {
  const [page, setPage] = useState("home");
  const [user, setUser] = useState(null);

  // Fix: define and pass onNavigate so Navbar never breaks
  const onNavigate = (newPage) => {
    setPage(newPage);
  };

  const onLogout = () => {
    setUser(null);
    setPage("home");
  };

  return (
    <>
      <Navbar onNavigate={onNavigate} onLogout={onLogout} user={user} />

      {/* SIMPLE PAGE SWITCHER */}
      {page === "home" && <Home />}
      {page === "about" && <About />}
      {page === "events" && <Events />}
      {page === "contact" && <div>Contact Section</div>}
      {page === "login" && <Login />}
      {page === "register" && <Register />}
      {page === "dashboard" && <div>User Dashboard</div>}

      <Chatbot />
    </>
  );
}
